INSERT INTO movimientos_inventario (variante_id,cambio,stock_final,motivo,referencia) SELECT id,1,1,'ingreso','Inventario inicial (Excel)' FROM producto_variantes WHERE producto_id=@p AND NOT EXISTS (SELECT 1 FROM movimientos_inventario m WHERE m.variante_id=producto_variantes.id);
